type Money struct {
    Amount   int64
    Currency string
}

// query: value receiver, returns a new value
func (m Money) Scale(num, den int64) Money {
    return Money{Amount: m.Amount * num / den, Currency: m.Currency}
}

// command: pointer receiver, no result
func (a *Account) Deposit(m Money) { a.balance += m.Amount }
